referenceSolutions.javascript:
export function validTree(n        , edges            )          {
if(edges.length!==n-1)return false;const parent=Array.from({length:n},(_,i)=>i);function find(x       )       {while(parent[x]!==x){parent[x]=parent[parent[x]];x=parent[x];}return x;}for(const [a,b] of edges){const x=find(a),y=find(b);if(x===y)return false;parent[x]=y;}return true;
}

